"""Frontier exploration with optional YOLO-World/MobileSAM object approach."""

import math
import time
from types import SimpleNamespace

import numpy as np
import rclpy
from geometry_msgs.msg import PoseStamped, Twist
from message_filters import ApproximateTimeSynchronizer, Subscriber
from nav2_msgs.action import ComputePathToPose, NavigateToPose
from nav_msgs.msg import OccupancyGrid
from rclpy.action import ActionClient
from rclpy.callback_groups import MutuallyExclusiveCallbackGroup
from rclpy.duration import Duration
from rclpy.executors import MultiThreadedExecutor
from rclpy.node import Node
from rclpy.qos import (DurabilityPolicy, HistoryPolicy, QoSProfile,
                       ReliabilityPolicy, qos_profile_sensor_data)
from rclpy.time import Time
from rcl_interfaces.msg import SetParametersResult
from sensor_msgs.msg import CameraInfo, Image
from std_msgs.msg import String
from tf2_ros import Buffer, TransformException, TransformListener
from visualization_msgs.msg import Marker, MarkerArray

from .navigation_algorithms import (grid_to_world, scan_yaws, select_frontier,
                                    standoff_candidates, within_radius,
                                    world_to_grid)


SEARCHING = "SEARCHING"
TARGET_CONFIRMED = "TARGET_CONFIRMED"
APPROACHING = "APPROACHING"
SUCCEEDED = "SUCCEEDED"
FAILED = "FAILED"


def yaw_quaternion(yaw):
    return (0.0, 0.0, math.sin(yaw / 2.0), math.cos(yaw / 2.0))


def quaternion_yaw(q):
    return math.atan2(2.0 * (q.w * q.z + q.x * q.y),
                      1.0 - 2.0 * (q.y * q.y + q.z * q.z))


def rotate_vector(q, vector):
    """Rotate a vector by geometry_msgs Quaternion without extra dependencies."""
    x, y, z, w = q.x, q.y, q.z, q.w
    matrix = np.array([
        [1 - 2 * (y*y + z*z), 2 * (x*y - z*w), 2 * (x*z + y*w)],
        [2 * (x*y + z*w), 1 - 2 * (x*x + z*z), 2 * (y*z - x*w)],
        [2 * (x*z - y*w), 2 * (y*z + x*w), 1 - 2 * (x*x + y*y)],
    ])
    return matrix @ np.asarray(vector, dtype=float)


class SemanticExplorer(Node):
    def __init__(self):
        super().__init__("semantic_explorer")
        defaults = {
            "enabled": False,
            "map_topic": "/map", "global_frame": "map", "base_frame": "base_link",
            "navigate_action": "/navigate_to_pose", "target_object": "chair",
            "detection_confidence": 0.65, "confirm_frames": 3,
            "confirmation_radius": 0.35, "standoff_distance": 0.8,
            "exploration_timeout": 120.0, "goal_reached_distance": 0.35,
            "min_frontier_cells": 8, "frontier_replan_period": 3.0,
            "enable_perception": False, "rgb_topic": "/camera/color/image_raw",
            "depth_topic": "/camera/aligned_depth_to_color/image_raw",
            "camera_info_topic": "/camera/color/camera_info",
            "camera_frame": "camera_color_optical_frame", "min_valid_depth_pixels": 30,
            "max_detection_depth": 4.0, "model_device": "cuda:0",
            "yolo_model_path": "/home/isee-cdh/ws/Co-NavGPT2/yolov8l-world.pt",
            "sam_model_path": "/home/isee-cdh/ws/Co-NavGPT2/mobile_sam.pt",
            "open_space_mode": False, "scan_first": True, "scan_steps": 8,
            "allow_frontier_after_scan": True, "max_travel_radius": 3.0,
            "test_timeout": 180.0, "tf_failure_timeout": 1.0,
            "target_lost_timeout": 10.0, "target_observation_attempts": 2,
            "publish_stop_command": True, "stop_cmd_topic": "/cmd_vel",
        }
        for name, value in defaults.items():
            self.declare_parameter(name, value)
        self.p = SimpleNamespace(**{name: self.get_parameter(name).value for name in defaults})

        self.map_message = None
        self.grid = None
        self.state = SEARCHING
        self.state_pub = self.create_publisher(String, "~/state", 10)
        self.marker_pub = self.create_publisher(MarkerArray, "~/markers", 10)
        self.stop_pub = self.create_publisher(Twist, self.p.stop_cmd_topic, 10)
        map_qos = QoSProfile(
            history=HistoryPolicy.KEEP_LAST, depth=1,
            reliability=ReliabilityPolicy.RELIABLE,
            durability=DurabilityPolicy.TRANSIENT_LOCAL)
        self.create_subscription(OccupancyGrid, self.p.map_topic, self.on_map, map_qos)
        self.tf_buffer = Buffer(cache_time=Duration(seconds=30.0))
        self.tf_listener = TransformListener(self.tf_buffer, self)
        self.navigator = ActionClient(self, NavigateToPose, self.p.navigate_action)
        self.path_planner = ActionClient(self, ComputePathToPose, "/compute_path_to_pose")

        self.goal_handle = None
        self.goal_pending = False
        self.goal_kind = None
        self.goal_started = 0.0
        self.goal_token = 0
        self.goal_pose = None
        self.plan_handle = None
        self.plan_pending = False
        self.plan_token = 0
        self.plan_candidates = []
        self.plan_kind = None
        self.blocked_goals = {}
        self.session_started = 0.0
        self.session_origin = None
        self.initial_yaw = 0.0
        self.scan_headings = []
        self.scan_index = 0
        self.target_observe_count = 0
        self.tf_missing_since = None
        self.last_frontier_goal = None
        self.target_position = None
        self.target_seen_time = 0.0
        self.confirm_positions = []
        self.last_inference = 0.0
        self.camera_info = None
        self.detector = None
        self.add_on_set_parameters_callback(self.on_parameters_changed)

        if self.p.enable_perception:
            # Model inference is intentionally isolated from the default group.
            # Parameter services and the navigation timer must remain responsive
            # while YOLO/SAM is processing a frame so `enabled=false` can act as
            # a prompt motion interlock.
            self.perception_group = MutuallyExclusiveCallbackGroup()
            self.create_subscription(CameraInfo, self.p.camera_info_topic, self.on_camera_info, 10)
            self.rgb_sub = Subscriber(
                self, Image, self.p.rgb_topic, qos_profile=qos_profile_sensor_data,
                callback_group=self.perception_group)
            self.depth_sub = Subscriber(
                self, Image, self.p.depth_topic, qos_profile=qos_profile_sensor_data,
                callback_group=self.perception_group)
            self.sync = ApproximateTimeSynchronizer([self.rgb_sub, self.depth_sub], 10, 0.10)
            self.sync.registerCallback(self.on_rgbd)
        else:
            self.get_logger().warn("Perception disabled: running frontier exploration only.")

        self.timer = self.create_timer(float(self.p.frontier_replan_period), self.tick)
        self.safety_timer = self.create_timer(0.2, self.safety_tick)
        self.publish_state()

    def publish_state(self):
        message = String()
        message.data = self.state
        self.state_pub.publish(message)

    def on_parameters_changed(self, parameters):
        """Make the runtime enable switch a real motion interlock."""
        for parameter in parameters:
            if parameter.name != "enabled":
                continue
            if not bool(parameter.value):
                self.cancel_goal(publish_stop=True)
            else:
                self.reset_session()
        return SetParametersResult(successful=True)

    def reset_session(self):
        self.cancel_goal(publish_stop=True)
        self.session_started = time.monotonic()
        self.session_origin = None
        self.scan_headings = []
        self.scan_index = 0
        self.target_observe_count = 0
        self.tf_missing_since = None
        self.target_position = None
        self.confirm_positions.clear()
        self.set_state(SEARCHING)

    def publish_stop(self):
        if not bool(self.p.publish_stop_command) or not rclpy.ok():
            return
        stop = Twist()
        # A short burst makes the stop visible even if a transport drops one
        # sample. Nav2 cancellation remains the primary motion stop mechanism.
        for _ in range(3):
            self.stop_pub.publish(stop)

    def set_state(self, state):
        if state != self.state:
            self.state = state
            self.get_logger().info(f"State -> {state}")
            self.publish_state()

    def on_map(self, message):
        expected = message.info.width * message.info.height
        if len(message.data) != expected or expected == 0:
            self.get_logger().warn("Ignoring malformed or empty OccupancyGrid")
            return
        self.map_message = message
        self.grid = np.asarray(message.data, dtype=np.int16).reshape(message.info.height, message.info.width)

    def robot_pose(self):
        try:
            transform = self.tf_buffer.lookup_transform(
                self.p.global_frame, self.p.base_frame, Time(), timeout=Duration(seconds=0.2))
            self.tf_missing_since = None
            return (transform.transform.translation.x,
                    transform.transform.translation.y,
                    quaternion_yaw(transform.transform.rotation))
        except TransformException as error:
            self.get_logger().warn(f"Robot TF unavailable: {error}", throttle_duration_sec=5.0)
            if self.tf_missing_since is None:
                self.tf_missing_since = time.monotonic()
            return None

    def robot_xy(self):
        pose = self.robot_pose()
        return pose[:2] if pose is not None else None

    def fail_safe(self, reason):
        self.get_logger().error(reason)
        self.cancel_goal(publish_stop=True)
        self.set_state(FAILED)

    def safety_tick(self):
        if not self.get_parameter("enabled").value or self.state in (SUCCEEDED, FAILED):
            return
        now = time.monotonic()
        if (bool(self.p.open_space_mode) and self.session_started and
                now - self.session_started > float(self.p.test_timeout)):
            self.fail_safe("Open-space test timeout exceeded")
            return
        pose = self.robot_pose()
        if pose is None:
            if (self.tf_missing_since is not None and
                    now - self.tf_missing_since > float(self.p.tf_failure_timeout)):
                self.fail_safe("Robot TF unavailable beyond safety timeout")
            return
        if (self.session_origin is not None and bool(self.p.open_space_mode) and
                not within_radius(pose[0], pose[1], self.session_origin,
                                  float(self.p.max_travel_radius))):
            self.fail_safe("Robot exceeded the configured test radius")
            return
        if (self.state == APPROACHING and self.target_position is not None and
                now - self.target_seen_time > float(self.p.target_lost_timeout)):
            self.get_logger().warn("Target lost during approach; stopping and returning to search")
            self.cancel_goal(publish_stop=True)
            self.target_position = None
            self.confirm_positions.clear()
            self.set_state(SEARCHING)

    def tick(self):
        if not self.get_parameter("enabled").value:
            return
        if self.grid is None or self.map_message is None or self.state in (SUCCEEDED, FAILED):
            return
        robot_pose = self.robot_pose()
        if robot_pose is None:
            return
        robot = robot_pose[:2]
        if self.session_origin is None:
            self.session_origin = robot
            self.initial_yaw = robot_pose[2]
            self.scan_headings = scan_yaws(self.initial_yaw, int(self.p.scan_steps))
            if not self.session_started:
                self.session_started = time.monotonic()
            self.get_logger().info(
                f"Test origin fixed at ({robot[0]:.2f}, {robot[1]:.2f}); "
                f"radius limit={float(self.p.max_travel_radius):.2f} m")
        if self.goal_handle is not None or self.goal_pending or self.plan_pending:
            if time.monotonic() - self.goal_started > float(self.p.exploration_timeout):
                if bool(self.p.open_space_mode):
                    self.fail_safe("Navigation goal timed out")
                else:
                    self.get_logger().warn("Navigation goal timed out; cancelling it")
                    self.cancel_goal(publish_stop=True)
            return

        if self.target_position is not None and self.state in (TARGET_CONFIRMED, APPROACHING):
            candidates = standoff_candidates(
                self.grid, self.target_position[:2], robot,
                (self.map_message.info.origin.position.x, self.map_message.info.origin.position.y),
                self.map_message.info.resolution,
                radii=(float(self.p.standoff_distance),
                       float(self.p.standoff_distance) + 0.2,
                       float(self.p.standoff_distance) + 0.4),
            )
            if candidates:
                poses = [
                    (x, y, yaw) for x, y, yaw, _ in candidates
                    if within_radius(x, y, self.session_origin,
                                     float(self.p.max_travel_radius))]
            else:
                poses = []
            if poses:
                self.plan_then_navigate(poses, "approach")
            else:
                self.observe_retained_target()
            return

        if bool(self.p.scan_first) and self.scan_index < len(self.scan_headings):
            yaw = self.scan_headings[self.scan_index]
            self.send_goal(robot[0], robot[1], yaw, "scan")
            return

        if not bool(self.p.allow_frontier_after_scan):
            self.fail_safe("Full in-place scan completed without finding the target")
            return

        cell = world_to_grid(
            robot[0], robot[1], self.map_message.info.origin.position.x,
            self.map_message.info.origin.position.y, self.map_message.info.resolution)
        selected, clusters = select_frontier(self.grid, cell, int(self.p.min_frontier_cells))
        self.publish_frontiers(clusters)
        if selected is None:
            self.fail_safe("No reachable frontier remains")
            return
        ordered = sorted(
            clusters,
            key=lambda cluster: len(cluster["cells"]) - 0.35 * cluster["distance_cells"],
            reverse=True)
        poses = []
        for cluster in ordered:
            x, y = grid_to_world(
                cluster["goal"][0], cluster["goal"][1],
                self.map_message.info.origin.position.x,
                self.map_message.info.origin.position.y,
                self.map_message.info.resolution)
            if within_radius(x, y, self.session_origin, float(self.p.max_travel_radius)):
                poses.append((x, y, math.atan2(y - robot[1], x - robot[0])))
        if not poses:
            self.fail_safe("No reachable frontier remains inside the configured test radius")
            return
        self.plan_then_navigate(poses, "frontier")

    @staticmethod
    def goal_key(pose):
        return round(float(pose[0]), 1), round(float(pose[1]), 1)

    def observe_retained_target(self):
        if self.target_position is None:
            self.set_state(SEARCHING)
            return
        robot = self.robot_xy()
        if robot is not None and self.target_observe_count < int(self.p.target_observation_attempts):
            self.target_observe_count += 1
            yaw = math.atan2(
                self.target_position[1] - robot[1],
                self.target_position[0] - robot[0])
            self.set_state(TARGET_CONFIRMED)
            self.get_logger().warn(
                "No usable standoff path yet; retaining target and turning to observe it")
            self.send_goal(robot[0], robot[1], yaw, "observe")
            return
        self.get_logger().warn(
            "Target observation attempts exhausted; resuming bounded search")
        self.target_position = None
        self.confirm_positions.clear()
        self.target_observe_count = 0
        self.set_state(SEARCHING)

    def plan_then_navigate(self, candidates, kind):
        """Ask Nav2 to validate candidates before any motion goal is sent."""
        now = time.monotonic()
        self.blocked_goals = {
            key: expiry for key, expiry in self.blocked_goals.items() if expiry > now}
        candidates = [
            tuple(candidate) for candidate in candidates
            if self.blocked_goals.get(self.goal_key(candidate), 0.0) <= now]
        if not candidates:
            self.get_logger().warn(f"No unblocked {kind} candidate is available")
            if kind == "approach":
                self.observe_retained_target()
            return
        if not self.path_planner.wait_for_server(timeout_sec=0.5):
            self.get_logger().warn("ComputePathToPose action server is not available")
            return
        self.plan_token += 1
        self.plan_pending = True
        self.plan_candidates = candidates
        self.plan_kind = kind
        self.goal_started = now
        self._request_next_plan(self.plan_token)

    def _request_next_plan(self, token):
        if token != self.plan_token:
            return
        if not self.plan_candidates:
            kind = self.plan_kind
            self.plan_pending = False
            self.plan_handle = None
            self.plan_kind = None
            self.get_logger().warn(f"Nav2 cannot plan to any {kind} candidate")
            if kind == "approach":
                self.observe_retained_target()
            return
        pose = self.plan_candidates.pop(0)
        self.current_plan_pose = pose
        goal = ComputePathToPose.Goal()
        goal.goal = PoseStamped()
        goal.goal.header.frame_id = self.p.global_frame
        goal.goal.header.stamp = self.get_clock().now().to_msg()
        goal.goal.pose.position.x = float(pose[0])
        goal.goal.pose.position.y = float(pose[1])
        qx, qy, qz, qw = yaw_quaternion(pose[2])
        goal.goal.pose.orientation.x = qx
        goal.goal.pose.orientation.y = qy
        goal.goal.pose.orientation.z = qz
        goal.goal.pose.orientation.w = qw
        goal.use_start = False
        future = self.path_planner.send_goal_async(goal)
        future.add_done_callback(lambda done: self.on_plan_response(done, token))

    def on_plan_response(self, future, token):
        if token != self.plan_token:
            return
        try:
            handle = future.result()
        except Exception as error:
            self.get_logger().warn(f"Path validation request failed: {error}")
            self.blocked_goals[self.goal_key(self.current_plan_pose)] = time.monotonic() + 15.0
            self._request_next_plan(token)
            return
        if not handle.accepted:
            self.blocked_goals[self.goal_key(self.current_plan_pose)] = time.monotonic() + 15.0
            self._request_next_plan(token)
            return
        self.plan_handle = handle
        result = handle.get_result_async()
        result.add_done_callback(lambda done: self.on_plan_result(done, token))

    def on_plan_result(self, future, token):
        if token != self.plan_token:
            return
        try:
            wrapped = future.result()
        except Exception as error:
            self.get_logger().warn(f"Cannot obtain path validation result: {error}")
            self.blocked_goals[self.goal_key(self.current_plan_pose)] = time.monotonic() + 15.0
            self.plan_handle = None
            self._request_next_plan(token)
            return
        pose = self.current_plan_pose
        path = wrapped.result.path.poses
        path_inside_boundary = all(
            within_radius(item.pose.position.x, item.pose.position.y,
                          self.session_origin, float(self.p.max_travel_radius))
            for item in path)
        if wrapped.status == 4 and len(path) >= 2 and path_inside_boundary:
            kind = self.plan_kind
            self.plan_pending = False
            self.plan_handle = None
            self.plan_candidates = []
            self.plan_kind = None
            if kind == "approach":
                self.set_state(APPROACHING)
            else:
                self.last_frontier_goal = pose[:2]
            self.send_goal(*pose, kind)
            return
        if wrapped.status == 4 and path and not path_inside_boundary:
            self.get_logger().warn("Rejecting path that leaves the configured test radius")
        self.blocked_goals[self.goal_key(pose)] = time.monotonic() + 15.0
        self.plan_handle = None
        self._request_next_plan(token)

    def send_goal(self, x, y, yaw, kind):
        if not self.navigator.wait_for_server(timeout_sec=0.5):
            self.get_logger().warn("NavigateToPose action server is not available")
            return
        goal = NavigateToPose.Goal()
        goal.pose = PoseStamped()
        goal.pose.header.frame_id = self.p.global_frame
        goal.pose.header.stamp = self.get_clock().now().to_msg()
        goal.pose.pose.position.x = float(x)
        goal.pose.pose.position.y = float(y)
        qx, qy, qz, qw = yaw_quaternion(yaw)
        goal.pose.pose.orientation.x, goal.pose.pose.orientation.y = qx, qy
        goal.pose.pose.orientation.z, goal.pose.pose.orientation.w = qz, qw
        self.goal_token += 1
        token = self.goal_token
        self.goal_kind = kind
        self.goal_pose = (float(x), float(y), float(yaw))
        self.goal_started = time.monotonic()
        self.goal_pending = True
        future = self.navigator.send_goal_async(goal)
        future.add_done_callback(lambda done: self.on_goal_response(done, token, kind))
        self.publish_navigation_goal(x, y, yaw, kind)
        self.get_logger().info(f"Sending {kind} goal: ({x:.2f}, {y:.2f})")

    def on_goal_response(self, future, token, kind):
        try:
            handle = future.result()
        except Exception as error:
            if token == self.goal_token:
                self.goal_pending = False
                self.fail_safe(f"{kind} goal request failed: {error}")
            return
        if token != self.goal_token:
            # A detection or timeout invalidated this request while Nav2 was
            # deciding whether to accept it. Cancel an accepted stale goal.
            if handle.accepted:
                handle.cancel_goal_async()
            return
        self.goal_pending = False
        if not handle.accepted:
            self.get_logger().warn(f"{kind} goal rejected")
            self.goal_handle = None
            if self.goal_pose is not None:
                self.blocked_goals[self.goal_key(self.goal_pose)] = time.monotonic() + 15.0
            if bool(self.p.open_space_mode):
                self.fail_safe(f"{kind} goal was rejected")
            elif kind == "approach":
                self.target_position = None
                self.set_state(SEARCHING)
            return
        self.goal_handle = handle
        result = handle.get_result_async()
        result.add_done_callback(lambda done: self.on_goal_result(done, token, kind))

    def on_goal_result(self, future, token, kind):
        if token != self.goal_token:
            return
        try:
            status = future.result().status
        except Exception as error:
            self.fail_safe(f"Cannot obtain {kind} goal result: {error}")
            return
        failed_pose = self.goal_pose
        self.goal_handle = None
        self.goal_pending = False
        self.goal_kind = None
        self.goal_pose = None
        if kind == "scan":
            if status == 4:
                self.scan_index += 1
                self.set_state(SEARCHING)
            else:
                self.fail_safe("In-place scan goal failed")
            return
        if kind == "observe":
            if status != 4:
                self.fail_safe("Target observation turn failed")
            return
        if kind == "approach" and status == 4:  # action_msgs/GoalStatus.STATUS_SUCCEEDED
            visible_recently = (
                time.monotonic() - self.target_seen_time < float(self.p.target_lost_timeout))
            robot = self.robot_xy()
            target_distance = (
                math.hypot(robot[0] - self.target_position[0], robot[1] - self.target_position[1])
                if robot is not None and self.target_position is not None else math.inf
            )
            max_distance = float(self.p.standoff_distance) + 0.4 + float(self.p.goal_reached_distance)
            if visible_recently and target_distance <= max_distance:
                self.set_state(SUCCEEDED)
                return
            self.get_logger().warn(
                f"Approach completed without final confirmation "
                f"(visible={visible_recently}, target_distance={target_distance:.2f} m)")
            self.target_position = None
        if kind == "approach" and status != 4:
            if failed_pose is not None:
                self.blocked_goals[self.goal_key(failed_pose)] = time.monotonic() + 15.0
            self.publish_stop()
            self.set_state(TARGET_CONFIRMED)
            return
        if status != 4 and failed_pose is not None:
            self.blocked_goals[self.goal_key(failed_pose)] = time.monotonic() + 15.0
        self.set_state(SEARCHING)

    def cancel_goal(self, publish_stop=False):
        self.goal_token += 1  # invalidate callbacks from the old goal
        self.plan_token += 1
        if self.plan_handle is not None:
            self.plan_handle.cancel_goal_async()
        if self.goal_handle is not None:
            self.goal_handle.cancel_goal_async()
        self.plan_handle = None
        self.plan_pending = False
        self.plan_candidates = []
        self.plan_kind = None
        self.goal_handle = None
        self.goal_pending = False
        self.goal_kind = None
        self.goal_pose = None
        if publish_stop:
            self.publish_stop()

    def on_camera_info(self, message):
        self.camera_info = message

    def ensure_detector(self):
        if self.detector is not None:
            return True
        try:
            from ultralytics import SAM, YOLO
            self.yolo = YOLO(self.p.yolo_model_path).to(self.p.model_device)
            self.yolo.set_classes([self.p.target_object])
            self.sam = SAM(self.p.sam_model_path).to(self.p.model_device)
            self.detector = True
            return True
        except Exception as error:
            self.get_logger().error(f"Cannot initialize perception models: {error}")
            self.set_state(FAILED)
            return False

    @staticmethod
    def image_array(message):
        channels = 3
        row = np.frombuffer(message.data, dtype=np.uint8).reshape(message.height, message.step)
        image = row[:, :message.width * channels].reshape(message.height, message.width, channels)
        return image[:, :, ::-1] if message.encoding.lower() == "rgb8" else image

    @staticmethod
    def depth_metres(message):
        row_bytes = message.step
        if message.encoding == "32FC1":
            row = np.frombuffer(message.data, dtype=np.uint8).reshape(message.height, row_bytes)
            return row[:, :message.width * 4].copy().view(np.float32).reshape(message.height, message.width)
        row = np.frombuffer(message.data, dtype=np.uint8).reshape(message.height, row_bytes)
        return row[:, :message.width * 2].copy().view(np.uint16).reshape(message.height, message.width) / 1000.0

    def on_rgbd(self, rgb_message, depth_message):
        if self.camera_info is None or self.state in (SUCCEEDED, FAILED):
            return
        if time.monotonic() - self.last_inference < 0.8:
            return
        self.last_inference = time.monotonic()
        if not self.ensure_detector():
            return
        image = self.image_array(rgb_message)
        depth = self.depth_metres(depth_message)
        results = self.yolo.predict(image, conf=float(self.p.detection_confidence), verbose=False)
        if not len(results[0].boxes):
            self.confirm_positions.clear()
            return
        boxes = results[0].boxes.xyxy
        sam_result = self.sam.predict(image, bboxes=boxes, verbose=False)[0]
        if sam_result.masks is None:
            return
        masks = sam_result.masks.data.cpu().numpy()
        confidences = results[0].boxes.conf.cpu().numpy()
        best = int(np.argmax(confidences))
        mask = masks[best].astype(np.uint8)
        if mask.shape != depth.shape:
            import cv2
            mask = cv2.resize(mask, (depth.shape[1], depth.shape[0]), interpolation=cv2.INTER_NEAREST)
        valid = (mask > 0) & np.isfinite(depth) & (depth > 0.15) & (depth < float(self.p.max_detection_depth))
        if np.count_nonzero(valid) < int(self.p.min_valid_depth_pixels):
            return
        rows, cols = np.nonzero(valid)
        z_values = depth[valid]
        z = float(np.median(z_values))
        # Median pixels near the median depth reject background leaking through a mask.
        near = np.abs(z_values - z) < 0.15
        u, v = float(np.median(cols[near])), float(np.median(rows[near]))
        fx, fy = self.camera_info.k[0], self.camera_info.k[4]
        cx, cy = self.camera_info.k[2], self.camera_info.k[5]
        camera_point = ((u - cx) * z / fx, (v - cy) * z / fy, z)
        try:
            transform = self.tf_buffer.lookup_transform(
                self.p.global_frame, self.p.camera_frame, Time.from_msg(depth_message.header.stamp),
                timeout=Duration(seconds=0.2))
        except TransformException as error:
            self.get_logger().warn(f"Image-time camera TF unavailable: {error}", throttle_duration_sec=5.0)
            return
        point = rotate_vector(transform.transform.rotation, camera_point)
        point += np.array([
            transform.transform.translation.x, transform.transform.translation.y,
            transform.transform.translation.z])
        self.confirm_detection(tuple(point))

    def confirm_detection(self, point):
        if self.confirm_positions:
            center = np.mean(self.confirm_positions, axis=0)
            if np.linalg.norm(np.asarray(point[:2]) - center[:2]) > float(self.p.confirmation_radius):
                self.confirm_positions.clear()
        self.confirm_positions.append(point)
        self.confirm_positions = self.confirm_positions[-int(self.p.confirm_frames):]
        self.target_seen_time = time.monotonic()
        if len(self.confirm_positions) < int(self.p.confirm_frames):
            return
        center = np.median(np.asarray(self.confirm_positions), axis=0)
        self.target_position = tuple(float(value) for value in center)
        self.publish_target_marker()
        if self.state == SEARCHING:
            self.target_observe_count = 0
            self.set_state(TARGET_CONFIRMED)
            self.cancel_goal(publish_stop=True)

    def publish_frontiers(self, clusters):
        markers = MarkerArray()
        clear = Marker()
        clear.action = Marker.DELETEALL
        markers.markers.append(clear)
        if self.map_message is None:
            self.marker_pub.publish(markers)
            return
        for index, cluster in enumerate(clusters):
            marker = Marker()
            marker.header.frame_id = self.p.global_frame
            marker.header.stamp = self.get_clock().now().to_msg()
            marker.ns, marker.id, marker.type, marker.action = "frontiers", index, Marker.SPHERE, Marker.ADD
            x, y = grid_to_world(cluster["goal"][0], cluster["goal"][1],
                                 self.map_message.info.origin.position.x,
                                 self.map_message.info.origin.position.y,
                                 self.map_message.info.resolution)
            marker.pose.position.x, marker.pose.position.y = x, y
            marker.pose.orientation.w = 1.0
            marker.scale.x = marker.scale.y = marker.scale.z = 0.18
            marker.color.b, marker.color.g, marker.color.a = 1.0, 0.5, 0.9
            markers.markers.append(marker)
        self.marker_pub.publish(markers)

    def publish_navigation_goal(self, x, y, yaw, kind):
        marker = Marker()
        marker.header.frame_id = self.p.global_frame
        marker.header.stamp = self.get_clock().now().to_msg()
        marker.ns = "approach_goal" if kind == "approach" else "frontier_goal"
        marker.id = 0
        marker.type = Marker.ARROW
        marker.action = Marker.ADD
        marker.pose.position.x = float(x)
        marker.pose.position.y = float(y)
        qx, qy, qz, qw = yaw_quaternion(yaw)
        marker.pose.orientation.x = qx
        marker.pose.orientation.y = qy
        marker.pose.orientation.z = qz
        marker.pose.orientation.w = qw
        marker.scale.x = 0.45
        marker.scale.y = 0.12
        marker.scale.z = 0.12
        if kind == "approach":
            marker.color.g = 1.0
        else:
            marker.color.b = 1.0
        marker.color.a = 1.0
        self.marker_pub.publish(MarkerArray(markers=[marker]))

    def publish_target_marker(self):
        marker = Marker()
        marker.header.frame_id = self.p.global_frame
        marker.header.stamp = self.get_clock().now().to_msg()
        marker.ns, marker.id, marker.type, marker.action = "target", 0, Marker.SPHERE, Marker.ADD
        marker.pose.position.x, marker.pose.position.y, marker.pose.position.z = self.target_position
        marker.pose.orientation.w = 1.0
        marker.scale.x = marker.scale.y = marker.scale.z = 0.30
        marker.color.r, marker.color.g, marker.color.a = 1.0, 0.2, 1.0
        self.marker_pub.publish(MarkerArray(markers=[marker]))


def main(args=None):
    rclpy.init(args=args)
    node = SemanticExplorer()
    # TF messages must be allowed to enter the buffer while an RGB-D callback
    # waits for the transform at the image timestamp.  A single-threaded
    # executor blocks the TransformListener callback and turns a small sensor
    # timing offset into a false "extrapolation into the future" failure.
    executor = MultiThreadedExecutor(num_threads=3)
    executor.add_node(node)
    try:
        executor.spin()
    except KeyboardInterrupt:
        pass
    finally:
        if rclpy.ok():
            node.cancel_goal(publish_stop=True)
        executor.remove_node(node)
        executor.shutdown()
        node.destroy_node()
        if rclpy.ok():
            rclpy.shutdown()
